widget.draw:
function draw(ctx, state, t) {
  function fmt(v) { return Math.round(v * 100) / 100; }
  var w = state.w;
  var h = state.h;
  var beta = state.beta;
  var dr = state.dr;
  var p = 1 / (1 + Math.exp(-dr / beta));
  var q = 1 - p;
  var rA = 2 + dr / 2;
  var rB = 2 - dr / 2;
  var maxW = 190;
  var rW_A = rA / 4 * maxW;
  var rW_B = Math.max(0, rB / 4 * maxW);
  var pW_A = p * maxW;
  var pW_B = q * maxW;
  ctx.clearRect(0, 0, w, h);
  ctx.fillStyle = "#f6f3ec";
  ctx.fillRect(0, 0, w, h);
  ctx.font = "13px sans-serif";
  ctx.textAlign = "left";
  ctx.textBaseline = "alphabetic";
  ctx.fillStyle = "#1d1a16";
  ctx.fillText("reward", 40, 30);
  ctx.fillText("policy", 340, 30);
  ctx.fillStyle = "#1f4b99";
  ctx.fillRect(40, 60, rW_A, 34);
  ctx.fillRect(40, 110, rW_B, 34);
  ctx.fillStyle = "#c4512c";
  ctx.fillRect(340, 60, pW_A, 34);
  ctx.fillStyle = "#1f4b99";
  ctx.fillRect(340, 110, pW_B, 34);
  ctx.fillStyle = "#1d1a16";
  ctx.font = "14px sans-serif";
  ctx.fillText("p_top = " + fmt(p), 40, 200);
  ctx.font = "12px sans-serif";
  if (p > 0.9) {
    ctx.fillText("one token takes the reward", 340, 200);
  } else {
    ctx.fillText("policy stays split", 340, 200);
  }
}
